voc:[["gli occhiali da sole","sunglasses"],["il costume da bagno","swimsuit"],["le scarpe da ginnastica","trainers"],["la sala da pranzo","dining room"],["da sogno","dream (adj.)"],["da poco","trivial"],["da solo","alone, by oneself"],["fare da guida","to act as a guide"],["da piccolo","as a child"],["avere da fare","to be busy"],["togliere il fiato","to take one's breath away"],["il proprietario","owner"],["il francobollo","stamp"],["la tazza","cup"],["il finestrino","car/train window"],["l'infanzia","childhood"]],
